class Solution:
    def orangesRotting(self, grid: List[List[int]]) -> int:
        from collections import deque

        m, n = len(grid), len(grid[0])
        queue = deque()
        fresh = 0

        # 1. 統計新鮮橘子，並把所有爛橘子一次放進佇列（多源）
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 2:
                    queue.append((i, j))
                elif grid[i][j] == 1:
                    fresh += 1

        # 一開始就沒有新鮮橘子
        if fresh == 0:
            return 0

        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        minutes = 0

        # 2. 逐層 BFS，每一層代表一分鐘
        while queue and fresh > 0:
            size = len(queue)              # 固定住「這一層」的數量
            for _ in range(size):
                x, y = queue.popleft()
                for dx, dy in directions:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] == 1:
                        grid[nx][ny] = 2   # 腐爛（同時當作已訪問標記）
                        fresh -= 1
                        queue.append((nx, ny))
            minutes += 1

        # 3. 若還有新鮮橘子，代表永遠爛不到
        return minutes if fresh == 0 else -1

