// 多源 BFS：所有腐爛的橘子同時當作起點，一層就是一分鐘
// 時間複雜度: O(m·n)，空間複雜度: O(m·n)
int orangesRotting(int** grid, int gridSize, int* gridColSize) {
    int m = gridSize, n = gridColSize[0];
    int* queue = malloc(sizeof(int) * m * n);      // 存 i * n + j
    int head = 0, tail = 0, fresh = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (grid[i][j] == 2) queue[tail++] = i * n + j;
            else if (grid[i][j] == 1) fresh++;
        }
    }

    const int dirs[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    int minutes = 0;
    while (head < tail && fresh > 0) {
        int levelEnd = tail;
        while (head < levelEnd) {
            int i = queue[head] / n, j = queue[head] % n;
            head++;
            for (int d = 0; d < 4; d++) {
                int x = i + dirs[d][0], y = j + dirs[d][1];
                if (x >= 0 && x < m && y >= 0 && y < n && grid[x][y] == 1) {
                    grid[x][y] = 2;
                    fresh--;
                    queue[tail++] = x * n + y;
                }
            }
        }
        minutes++;
    }
    free(queue);
    return fresh == 0 ? minutes : -1;
}

